namespace Aster.Editor {
[InitializeOnLoad] public static class AsterProjectSetup {
 const string Main="Assets/Scenes/Main.unity";
 static AsterProjectSetup(){EditorApplication.delayCall+=FirstOpen;}
 static void FirstOpen(){if(EditorApplication.isCompiling||EditorApplication.isUpdating){EditorApplication.delayCall+=FirstOpen;return;}if(!File.Exists(Main)&&AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Art/World.fbx"))Prepare();}
 [MenuItem("Aster/Prepare project (preserves Main scene)")]
 public static void Prepare(){Directory.CreateDirectory("Assets/Scenes");Directory.CreateDirectory("Assets/Materials");Directory.CreateDirectory("Assets/XR");AssetDatabase.Refresh();
 PlayerSettings.companyName="Aster";PlayerSettings.productName="Bi Mat Khu Di Tich";PlayerSettings.SetApplicationIdentifier(UnityEditor.Build.NamedBuildTarget.Android,"vn.aster.ruins");PlayerSettings.defaultInterfaceOrientation=UIOrientation.LandscapeLeft;PlayerSettings.colorSpace=ColorSpace.Linear;PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel24;PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.Android,false);PlayerSettings.SetGraphicsAPIs(BuildTarget.Android,new[]{GraphicsDeviceType.OpenGLES3});PlayerSettings.defaultScreenWidth=1600;PlayerSettings.defaultScreenHeight=900;
 SetupAR();if(!File.Exists(Main))CreateScene();EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Main,true)};AssetDatabase.SaveAssets();Debug.Log("ASTER: project prepared. Open Assets/Scenes/Main.unity and press Play. Existing Main scene preserved.");}
 static void CreateScene(){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Art/World.fbx");if(!prefab){Debug.LogError("World.fbx not found.");return;}var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var world=(GameObject)PrefabUtility.InstantiatePrefab(prefab);world.name="World";PrefabUtility.UnpackPrefabInstance(world,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
 ApplyMaterials(world);
 var game=new GameObject("Expedition").AddComponent<Expedition>();game.world=world.transform;var sun=new GameObject("Warm afternoon sun").AddComponent<Light>();sun.type=LightType.Directional;sun.color=new Color(1,.88f,.69f);sun.intensity=1.2f;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(48,-35,0);RenderSettings.sun=sun;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.51f,.63f,.70f);RenderSettings.ambientEquatorColor=new Color(.40f,.46f,.41f);RenderSettings.ambientGroundColor=new Color(.26f,.25f,.18f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=new Color(.67f,.74f,.68f);RenderSettings.fogStartDistance=45;RenderSettings.fogEndDistance=115;
 var sky=new Material(Shader.Find("Skybox/Procedural"));sky.SetFloat("_AtmosphereThickness",.85f);sky.SetColor("_SkyTint",new Color(.60f,.72f,.78f));AssetDatabase.CreateAsset(sky,"Assets/Materials/AsterSky.mat");RenderSettings.skybox=sky;QualitySettings.antiAliasing=4;QualitySettings.shadowDistance=38;QualitySettings.vSyncCount=1;EditorSceneManager.SaveScene(scene,Main);}
 static void ApplyMaterials(GameObject world){
 var materials=new System.Collections.Generic.Dictionary<string,Material>();foreach(var renderer in world.GetComponentsInChildren<Renderer>(true)){var list=renderer.sharedMaterials;for(int i=0;i<list.Length;i++){var src=list[i];if(!src)continue;string name=src.name.Replace(" (Instance)","");if(!materials.TryGetValue(name,out var mat)){string path="Assets/Materials/"+name+".mat";mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find(name=="Water"?"Aster/Water":"Standard"));mat.name=name;mat.color=src.HasProperty("_Color")?src.color:new Color(.7f,.6f,.4f);if(mat.HasProperty("_Glossiness"))mat.SetFloat("_Glossiness",name.StartsWith("Gold")?.5f:.14f);if(mat.HasProperty("_Metallic"))mat.SetFloat("_Metallic",name.StartsWith("Gold")?.45f:0);if(name=="Flame"){mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",new Color(1,.55f,.12f)*1.6f);}AssetDatabase.CreateAsset(mat,path);}Undo.RecordObject(mat,"Update Aster material");mat.color=src.HasProperty("_Color")?src.color:mat.color;if(name.StartsWith("KayKit_")){mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/Art/Textures/KayKit_dungeon_texture.png");mat.color=name=="KayKit_Stone"?new Color(1,.86f,.61f):new Color(.90f,.89f,.78f);}EditorUtility.SetDirty(mat);materials[name]=mat;}list[i]=mat;}renderer.sharedMaterials=list;}
 foreach(var r in world.GetComponentsInChildren<Renderer>()){bool moving=false;for(Transform t=r.transform;t&&t!=world.transform;t=t.parent)if(t.name.StartsWith("I_")||t.name.StartsWith("A_")){moving=true;break;}if(!moving)GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.BatchingStatic);}
}
 [MenuItem("Aster/Update artwork in current scene")]
 public static void UpdateArtwork(){
 if(EditorApplication.isPlaying){Debug.LogWarning("Stop Play mode before updating artwork.");return;}
 var game=Object.FindFirstObjectByType<Expedition>();if(!game||!game.world){Debug.LogError("Open Main scene first.");return;}
 var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Art/World.fbx");if(!prefab)return;Directory.CreateDirectory("Assets/Materials");
 var old=game.world;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Update Aster artwork");
 var replacement=(GameObject)PrefabUtility.InstantiatePrefab(prefab);replacement.name="World";PrefabUtility.UnpackPrefabInstance(replacement,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);replacement.transform.SetPositionAndRotation(old.position,old.rotation);replacement.transform.localScale=old.localScale;ApplyMaterials(replacement);Undo.RegisterCreatedObjectUndo(replacement,"New artwork");
 Undo.RecordObject(game,"Connect artwork");Undo.RecordObject(old.gameObject,"Keep old artwork backup");old.gameObject.name="World_ArtworkBackup";old.gameObject.SetActive(false);game.world=replacement.transform;Undo.CollapseUndoOperations(group);EditorSceneManager.MarkSceneDirty(game.gameObject.scene);Debug.Log("ASTER: artwork updated. Old world kept inactive as World_ArtworkBackup. Save when satisfied. Undo restores scene references, not overwritten asset files.");
 }
 static void SetupAR(){var texture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/AR/DiscCard.png");var lib=AssetDatabase.LoadAssetAtPath<XRReferenceImageLibrary>("Assets/Resources/AR/DiscLibrary.asset");if(!lib&&texture){lib=ScriptableObject.CreateInstance<XRReferenceImageLibrary>();lib.Add();lib.SetName(0,"DiscCard");lib.SetTexture(0,texture,true);lib.SetSpecifySize(0,true);lib.SetSize(0,new Vector2(.15f,.15f));AssetDatabase.CreateAsset(lib,"Assets/Resources/AR/DiscLibrary.asset");}
 XRGeneralSettingsPerBuildTarget perTarget;if(!EditorBuildSettings.TryGetConfigObject(XRGeneralSettings.k_SettingsKey,out perTarget)){perTarget=ScriptableObject.CreateInstance<XRGeneralSettingsPerBuildTarget>();AssetDatabase.CreateAsset(perTarget,"Assets/XR/XRGeneralSettings.asset");EditorBuildSettings.AddConfigObject(XRGeneralSettings.k_SettingsKey,perTarget,true);}var settings=perTarget.SettingsForBuildTarget(BuildTargetGroup.Android);if(!settings){settings=ScriptableObject.CreateInstance<XRGeneralSettings>();settings.name="Android XR";AssetDatabase.AddObjectToAsset(settings,perTarget);perTarget.SetSettingsForBuildTarget(BuildTargetGroup.Android,settings);}if(!settings.Manager){var manager=ScriptableObject.CreateInstance<XRManagerSettings>();manager.name="Android XR Manager";AssetDatabase.AddObjectToAsset(manager,perTarget);settings.Manager=manager;}settings.InitManagerOnStart=true;XRPackageMetadataStore.AssignLoader(settings.Manager,"UnityEngine.XR.ARCore.ARCoreLoader",BuildTargetGroup.Android);EditorUtility.SetDirty(settings);EditorUtility.SetDirty(settings.Manager);EditorUtility.SetDirty(perTarget);}
 [MenuItem("Aster/Validate scene anchors")]
 public static void Validate(){var g=Object.FindFirstObjectByType<Expedition>();if(!g||!g.world){Debug.LogError("Open Main scene first.");return;}string[] names={"P_Spawn","P_Look","P_Courtyard","P_Water","P_End","P_Inspect","I_Disc","I_Journal","I_Flashlight","I_GateLever","I_Shutter","I_Handle","I_Valve","I_MachineLever","I_FinalValve","A_GateLeft","A_GateRight","A_FinalLeft","A_FinalRight","A_SideGate","A_Shutter","A_PoolWater","A_Waterwheel","P_Receiver"};var set=new System.Collections.Generic.HashSet<string>();foreach(var t in g.world.GetComponentsInChildren<Transform>(true))set.Add(t.name);int missing=0;foreach(string n in names)if(!set.Contains(n)){Debug.LogError("Missing: "+n);missing++;}foreach(string prefix in new[]{"I_Ring","I_Channel","I_Gear","I_Socket","A_Gear","I_Note"})for(int i=0;i<3;i++)if(!set.Contains(prefix+i)){Debug.LogError("Missing: "+prefix+i);missing++;}for(int i=0;i<2;i++)if(!set.Contains("I_Mirror"+i))missing++;Debug.Log("ASTER anchor validation: "+missing+" missing.");}
}
public class AsterImport:AssetPostprocessor {
 void OnPreprocessModel(){if(!assetPath.StartsWith("Assets/Resources/Art/"))return;var m=(ModelImporter)assetImporter;m.importAnimation=false;m.importCameras=false;m.importLights=false;m.globalScale=1;m.importNormals=ModelImporterNormals.Import;m.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;}
 void OnPreprocessAudio(){if(!assetPath.StartsWith("Assets/Resources/Audio/"))return;var a=(AudioImporter)assetImporter;var s=a.defaultSampleSettings;s.compressionFormat=AudioCompressionFormat.Vorbis;s.quality=.7f;s.loadType=assetPath.Contains("exploration")||assetPath.Contains("forest")||assetPath.Contains("ending")?AudioClipLoadType.Streaming:AudioClipLoadType.DecompressOnLoad;a.defaultSampleSettings=s;}
 void OnPreprocessTexture(){if(assetPath.StartsWith("Assets/Resources/Nature/")){var nature=(TextureImporter)assetImporter;nature.maxTextureSize=1024;nature.mipmapEnabled=true;if(assetPath.Contains("_Normal"))nature.textureType=TextureImporterType.NormalMap;return;}if(!assetPath.Contains("DiscCard"))return;var t=(TextureImporter)assetImporter;t.isReadable=true;t.mipmapEnabled=false;t.textureCompression=TextureImporterCompression.Uncompressed;t.maxTextureSize=1024;}
}
}
